#!/usr/bin/env bash
# PRODUCTION START (API) — Riyadh Trust Bank (v0.8)
#
# Starts the production API on :8000 with production env loaded from
# .env.production (generated by scripts/production_setup.sh).
# Foreground — Ctrl+C stops it. Single worker, no --reload, no Server
# header (uvicorn --no-server-header). Dev (:8000) and production
# (:8000) share the port on purpose — production IS the live instance
# on this machine; stop dev/staging before starting production, or
# the bind will fail (see docs/PRODUCTION.md § Runbook).
#
# Usage:  ./scripts/production_start.sh
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
VENV="${RTB_PROD_VENV:-$HOME/rtb-prod-venv}"

if [ ! -f "$ROOT/.env.production" ]; then
    echo "ERROR: $ROOT/.env.production not found — run ./scripts/production_setup.sh first."
    exit 1
fi
if grep -q "REPLACE-ME-WITH-A-LONG-RANDOM-SECRET" "$ROOT/.env.production"; then
    echo "ERROR: .env.production still has the placeholder SECRET_KEY."
    echo "Run ./scripts/production_setup.sh to generate a real one, or set it by hand:"
    echo '  python -c "import secrets; print(secrets.token_urlsafe(64))"'
    exit 1
fi
if [ ! -x "$VENV/bin/python" ]; then
    echo "ERROR: production venv not found at $VENV — run ./scripts/production_setup.sh first."
    exit 1
fi

# Load production env (SECRET_KEY, DATABASE_URL, CORS_ORIGINS, ...).
# shellcheck disable=SC1091
set -a
# shellcheck source=/dev/null
. "$ROOT/.env.production"
set +a
# Always force the production data dir to the absolute path, even if
# the .env.production line was edited to something relative.
export RTB_DATA_DIR="$ROOT/data-prod"
export ENVIRONMENT=production

echo "Production API starting on http://127.0.0.1:8000"
echo "  ENVIRONMENT=$ENVIRONMENT  RTB_DATA_DIR=$RTB_DATA_DIR"
echo "  DATABASE_URL=<redacted>"
echo "  Demo accounts: OFF (RTB_DEMO_ACCOUNTS=${RTB_DEMO_ACCOUNTS:-0})"
echo "  Health: python scripts/healthcheck.py"
cd "$ROOT/backend"
# shellcheck disable=SC1091
source "$VENV/bin/activate"
exec "$VENV/bin/python" -m uvicorn app.main:app --port 8000 --no-server-header
